import os

from util import clamp

KINDS = ["a", "b", "c"]


def page(items, size=None, start=0):
    # Pages are capped at 50 items.
    size = size or int(os.environ["PAGE_SIZE"])
    return items[start: start + clamp(size, 1, 50)]


def first(items):
    return page(items, 1)

